-- Changelog-item: opleverrapport mailen (PDF-bijlage) + automatisch klaargezette herinneringen.

insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-17','nieuw','Oplevering','Opleverrapport mailen en automatische herinneringen',
   'Je kunt het opleverrapport nu rechtstreeks naar de opdrachtgever en andere betrokkenen mailen, met een nette PDF als bijlage waarin alle opleverpunten, foto''s en handtekeningen staan. EVA zet daarnaast zelf berichten klaar: een herinnering aan onderaannemers die nog punten hebben openstaan, en een uitnodiging voor de bewonersvragenlijst na de oplevering. Alles wat klaarstaat zie je in het Mail-blok op de Oplevering-tab en gaat pas weg zodra jij op versturen klikt.');
